4|import { rankCallers } from '../rank.js';
5|import { enforceBudget } from '../budget.js';
6|import { collapseCallerEdges, expandClassRollupTargets } from './target_rollup.js';
7|import { inspectReadFreshness, prefixReadWarnings, staleNotFoundCaveat } from './read_freshness.js';
8|import { loadManifest } from '../../freshness/manifest.js';
9|import { computeTrustLevel } from './health.js';
10|import { getUnresolvedCounts } from '../../freshness/unresolved-metrics.js';
11|import { buildTrustLine, buildAbsenceTrustLine, hasLspVerifiedEdge, ABSENCE_TRUST_UNAVAILABLE, RESULTS_TRUST_UNAVAILABLE } from '../lsp-evidence.js';
12|import { EXECUTION_FAMILY, CALL_FAMILY } from '../../storage/taxonomy.js';
13|import { normalizePathArg } from '../../util/paths.js';
14|import { noMatchMessage } from '../did-you-mean.js';
15|// ⚠ Shared with graph_callees, which has the identical defect mirrored onto outgoing edges.
16|// One owner: fixing one verb and pasting into the other is how the two drift apart.
17|import { unsearchedRelationNote } from '../unsearched-scope.js';
18|import { indexedScopePhrase } from '../miss-scope.js';
19|import { isOvercountSuspicious, describeResultCount } from '../overcount-risk.js';
20|
21|const EXECUTION_RELATIONS = EXECUTION_FAMILY;
22|
23|// ⛔ THE RELATIONS THIS VERB DELIBERATELY DOES NOT SEARCH. Derived by SUBTRACTING one family from
24|// the other, never listed — the moment a relation joins CALL_FAMILY it belongs here automatically,
25|// and a hand-written copy would silently stop covering it.
26|const UNSEARCHED_RELATIONS = Object.freeze(CALL_FAMILY.filter((r) => !EXECUTION_FAMILY.includes(r)));
27|
28|// Hard ceiling on caller edges pulled from SQL. Distinct from the `top_k` display
29|// budget: past THIS the rows were never fetched, so the trust banner cannot claim
30|// the caller set is complete.
31|const EDGE_FETCH_CAP = 100;
32|
33|export async function graphCallers({ repoRoot, symbol, depth = 1, top_k = 10, file }) {
34|  file = normalizePathArg(file); // accept Windows backslash dir/path filters
35|  if (!symbol) return 'ERROR: symbol parameter is required';
36|  const freshness = await inspectReadFreshness({ repoRoot, verbName: 'graph_callers' });
37|  if (freshness.blocker) return freshness.blocker;
38|  const db = openExistingDb(join(repoRoot, '.aify-graph', 'graph.sqlite'));
39|  try {
40|    const { targets, targetIds, rolledUp, header, error } = expandClassRollupTargets(db, symbol, { withCallerSets: true });
41|    if (error) return error;
42|    // ⛔ A NOT-FOUND IS A CLAIM, AND A STALE INDEX MAKES IT A FALSE ONE. `staleNotFoundCaveat` is
43|    // MEASURED (n commits behind HEAD) and SILENT on a fresh index, so it adds no noise on the happy
44|    // path — the standard the whereis miss-scope work set: a generic "may be incomplete" costs the
45|    // reader as much as a false claim. find/search/whereis already did this; these did not.
46|    if (targets.length === 0) return [noMatchMessage(db, symbol), staleNotFoundCaveat(freshness)].filter(Boolean).join('\n');
47|
48|    const placeholders = targetIds.map((_, i) => `$t${i}`).join(',');
49|    const params = {};
50|    targetIds.forEach((id, i) => { params[`t${i}`] = id; });
51|
52|    // The SQL cap is a HARDER ceiling than the top_k display budget: past it the
53|    // edges were never fetched, so raising top_k cannot reveal them and the trust
54|    // banner must not claim an exhaustive caller set. Fetch one extra row purely
55|    // to detect that we hit it.
56|    let edges;
57|    if (depth <= 1) {
58|      edges = db.all(
59|        `SELECT e.*, n.label AS from_label, n.type AS from_type, n.file_path AS from_file, n.start_line AS from_line
60|         FROM edges e JOIN nodes n ON n.id = e.from_id
61|         WHERE e.to_id IN (${placeholders}) AND e.relation IN (${EXECUTION_RELATIONS.map((relation) => `'${relation}'`).join(',')})
62|         LIMIT ${EDGE_FETCH_CAP + 1}`,
63|        params
64|      );
65|    } else {
66|      edges = db.all(
67|        `WITH RECURSIVE callers(from_id, to_id, depth) AS (
68|           SELECT from_id, to_id, 1
69|           FROM edges
70|           WHERE to_id IN (${placeholders}) AND relation IN (${EXECUTION_RELATIONS.map((relation) => `'${relation}'`).join(',')})
71|           UNION ALL
72|           SELECT e.from_id, e.to_id, c.depth + 1
73|           FROM edges e
74|           JOIN callers c ON e.to_id = c.from_id
75|           WHERE e.relation IN (${EXECUTION_RELATIONS.map((relation) => `'${relation}'`).join(',')}) AND c.depth < $depth AND c.depth <= 10
76|         )
77|         SELECT DISTINCT e.*, n.label AS from_label, n.type AS from_type, n.file_path AS from_file, n.start_line AS from_line, c.depth
78|         FROM callers c
79|         JOIN edges e
80|           ON e.from_id = c.from_id
81|          AND e.to_id = c.to_id
82|          AND e.relation IN (${EXECUTION_RELATIONS.map((relation) => `'${relation}'`).join(',')})
83|         JOIN nodes n ON n.id = e.from_id
84|         LIMIT ${EDGE_FETCH_CAP + 1}`,
85|        { ...params, depth }
86|      );
87|    }
88|
89|    const edgesTruncated = edges.length > EDGE_FETCH_CAP;
90|    if (edgesTruncated) edges = edges.slice(0, EDGE_FETCH_CAP);
91|
92|    // I1 / R2-2026-05-31 — an absence claim ("NO CALLERS") is the most dangerous
93|    // output. Graph-edge traversal can never honestly attest an EXHAUSTIVE
94|    // absence (it reads edges, not live per-symbol clangd evidence), so route
95|    // through buildAbsenceTrustLine — which ALWAYS emits the heuristic
96|    // non-exhaustive caveat pointing at code_intel_references — never a bare
97|    // "NO CALLERS" and never a "trustworthy/exhaustive absence".
98|    const absence = async (msg) => {
99|      // ⛔ READ THE DATABASE BEFORE THE FIRST AWAIT. This function is async and its callers `return`
100|      // its promise, so the enclosing `finally { db.close() }` runs while that promise is still
101|      // pending — any db access AFTER an await here fails with "The database connection is not
102|      // open". Placed after the await, the scope note threw on every call and its catch returned
103|      // '', so the feature was inert and the output looked exactly as it had before.
104|      const scope = unsearchedRelationNote({
105|        db, column: 'to_id', placeholders, params, symbol,
106|        searched: EXECUTION_RELATIONS, unsearched: UNSEARCHED_RELATIONS,
107|        // ⚠ graph_impact, NOT graph_preflight: the default tool profile does not list preflight,
108|        // and the repo's remedy-reachability guard rejects pointing a reader at an uncallable verb.
109|        remedy: 'graph_impact answers "who touches this" across the wider family.',
110|      });
111|      let line = '';
112|      // The language comes from the resolved target, so the construct-coverage clause appears on a
113|      // C/C++ absence and costs zero bytes anywhere else.
114|      try { line = '\n' + await buildAbsenceTrustLine({ noun: 'callers', db, repoRoot, freshness, language: targets[0]?.language }); }
115|      // ⛔ NOT an empty catch. Measured 2026-09-02: swallowing this shipped a BARE absence with no
116|      // TRUST, no SCOPE and no NOT MODELLED — indistinguishable from an authoritative "nothing calls
117|      // this". The answer still returns; the agent is told the caveat is missing.
118|      catch { line = '\n' + ABSENCE_TRUST_UNAVAILABLE; }
119|      // ⚠ The scope note goes WITH the absence claim, where the reader is deciding whether nothing
120|      // uses this symbol — not into a separate field they would have to know to consult.
121|      return prefixReadWarnings(msg + line + scope, freshness.warnings);
122|    };
123|
124|    if (edges.length === 0) return absence(`NO CALLERS for "${symbol}"${indexedScopePhrase(db)}. Try graph_whereis(symbol="${symbol}", expand=true) for an overview.`);
125|
126|    // NOTE (P0-4): `source_file`/`source_line` here carry the CALLER's
127|    // DECLARATION location, not the call site. That is deliberate — edges are
128|    // function-granular (see docs/known-limitations.md), so one edge can stand
129|    // for several call sites inside the caller and there is no single call-site
130|    // line to show. It is also what makes the `file` directory filter below mean
131|    // "callers living under this path". The location is honest data; what was
132|    // NOT honest was rendering it in a format that reads as a call site, so the
133|    // output now says which it is (see LOCATIONS note below).
134|    let mapped = edges.map(e => ({
135|      from_id: e.from_id, to_id: e.to_id, relation: e.relation,
136|      source_file: e.from_file, source_line: e.from_line,
137|      confidence: e.confidence,
138|      provenance: e.provenance ?? 'EXTRACTED',
139|      depth: e.depth ?? 1,
140|      from_type: e.from_type, fan_in: 1,
141|      from_label: e.from_label,
142|      to_label: symbol,
143|    }));
144|    if (rolledUp) mapped = collapseCallerEdges(mapped, symbol);
145|    // File scope filter: only show callers from a specific directory
146|    if (file) mapped = mapped.filter(e => e.source_file && e.source_file.startsWith(file));
147|    if (mapped.length === 0) return absence(file ? `NO CALLERS from "${file}"${indexedScopePhrase(db)}` : `NO CALLERS for "${symbol}"${indexedScopePhrase(db)}. Try graph_whereis(symbol="${symbol}", expand=true) for an overview.`);
148|    const ranked = rankCallers(mapped);
149|    const { kept, dropped } = enforceBudget(ranked, top_k);
150|    const body = renderCompact({ nodes: [], edges: kept, truncated: dropped, suggestion: `top_k=${top_k + 10}`, truncatedIsFloor: edgesTruncated });
151|
152|    // CONFIDENCE footer — same pattern as graph_impact (added 2026-04-27).
153|    // Echoes IMPACT bench showed graph_impact silently undercounting C++
154|    // method callers at trust=weak; graph_callers shares the same risk.
155|    let confidenceFooter = '';
156|    try {
157|      const { manifest } = await loadManifest(join(repoRoot, '.aify-graph'));
158|      const { trust: trustCount } = getUnresolvedCounts(manifest ?? {});
159|      const trust = computeTrustLevel(trustCount);
160|      const occRow = db.get(
161|        `SELECT COUNT(*) AS c FROM nodes WHERE label = $label`,
162|        { label: symbol },
163|      );
164|      const occurrences = occRow?.c ?? 0;
165|      const resultCount = mapped.length;
166|      // Same trigger as graph_impact: only fire when result actually
167|      // looks suspicious. Trust=strong with healthy count stays quiet.
168|      // ⭐ ONE OWNER. This predicate used to live here AND in the other verb, byte-identical, and
169|      // it had the same hole in both: it modelled AMBIGUITY and was blind to the builtin-method
170|      // COLLISION that `graph_callers("has")` produces. See overcount-risk.js.
171|      const { suspicious } = isOvercountSuspicious({
172|        trust, resultCount, occurrences, symbol, hasVerifiedEdge: hasLspVerifiedEdge(mapped),
173|      });
174|      if (suspicious) {
175|        // ⛔ THE LEAN THIS BLOCK USED TO CARRY, TWO LINES BELOW THE SENTENCE THAT WITHDREW IT.
176|        //
177|        // `HEURISTIC_TRUST_LINE` was repaired to name BOTH directions after `graph_callers("has")`
178|        // returned 100 callers that were nearly all `Map.has()`. This footer — the half carrying
179|        // the NUMBERS, and the more authoritative-looking one — still said only "Likely undercount"
180|        // and "may hide additional sites". the field test, field-testing the fix: "the subset story
181|        // restated, immediately after the sentence that withdrew it. A reader who takes the last
182|        // word takes the wrong one."
183|        //
184|        // ⇒ THIRD TIME IN ONE SESSION a repair landed in one surface and left the claim standing in
185|        // another: a retracted H1 over a corrected body, a reasoning comment fixed while the printed
186|        // output still said 38%, and now TRUST fixed while CONFIDENCE leaned. ⇒ When a claim is
187|        // withdrawn, grep for every surface that restates it before calling the fix done.
188|        //
189|        // ⚠ AND THE DIRECTION MATTERS MORE HERE THAN ANYWHERE. the field test, asked directly whether
190|        // the old wording would have misled them: "YES… 'may undercount' says the list is a floor,
191|        // and a floor licenses acting on what IS shown — that is the whole value of a floor." So it
192|        // did not merely omit the overcount; it named the direction that makes a list SAFE TO USE.
193|        const overcountRisk = occurrences >= 2 || symbol.length <= 8;
194|        // ⛔ A CAP IS NOT A COUNT. `resultCount` saturates at EDGE_FETCH_CAP, and printing it bare
195|        // told a live agent "100 callers" for a symbol with 10 call sites in one function. The
196|        // truncation flag already existed and reached the trust banner while never reaching the
197|        // line that prints the number — computed and not consumed.
198|        const counted = describeResultCount({ resultCount, truncated: edgesTruncated });
199|        confidenceFooter = `\nCONFIDENCE: ${counted.text} callers · trust=${trust} · ${occurrences} indexed nodes labeled "${symbol}" · ${trustCount} unresolved CALLS edges not attributed to any caller.`
200|          + `\n  ⚠ This list is NOT a floor. On a weak-trust graph it can UNDERCOUNT (C++ cross-file`
201|          + ` dispatch, PHP traits/Eloquent, dynamic dispatch) and, because heuristic edges resolve`
202|          + ` calls BY NAME, it can also OVERCOUNT with unrelated same-named calls`
203|          + `${overcountRisk ? ' — and this symbol is exactly the shape that overcounts' : ''}.`
204|          + `\n  Verify with: rg -n "${symbol}\\b" before any deletion, rename, or signature change.`;
205|      }
206|    } catch { /* defensive */ }
207|
208|    // TRUST banner (Code-Intel v2 / L2b). One line, always present: either
209|    // `lsp-verified (...)` when the result carries clangd ground-truth edges
210|    // (with a STALE caveat when the collection is out of date) or the
211|    // heuristic-only undercount caveat. Shared helper so all four verbs agree.
212|    let trustLine = '';
213|    try {
214|      // M5: pass the queried symbol's own file so this banner and
215|      // code_intel_references compute the SAME coverage verdict, instead of one
216|      // granting the verified banner while the other returns exhaustive:false.
217|      trustLine = '\n' + await buildTrustLine({
218|        edges: mapped, db, repoRoot, truncated: edgesTruncated,
219|        file: targets?.[0]?.file_path ?? null,
220|        // A NON-EMPTY caller set is the answer an agent acts on, and it was the one result shape
221|        // carrying no word about the agent's own uncommitted work. Relevance-gated inside, so a
222|        // dirty tree alone says nothing — only a file that MENTIONS this symbol does.
223|        freshness, symbol,
224|      });
225|    // ⛔ Still never BLOCKS the result — but no longer silent; see lsp-evidence.js
226|    // RESULTS_TRUST_UNAVAILABLE.
227|    } catch { trustLine = '\n' + RESULTS_TRUST_UNAVAILABLE; }
228|
229|    // P0-4: state what the printed locations ARE. The Sand Castle field test
230|    // scored graph_callers 0/8 on a call-site census because its `file:line`
231|    // values (function declarations) were read as call sites. The data was
232|    // right; the label was missing.
233|    const locationsNote = '\nLOCATIONS: each file:line is the CALLER FUNCTION\'s declaration, not a call site '
234|      + '(edges are function-granular — one caller may contain several call sites). '
235|      // -F (fixed-string): a symbol like `ns::foo(int)` interpolated into a regex
236|      // makes `(int)` a capture group, which silently matches `ns::fooint`.
237|      + `For exact call-site lines use code_intel_references, or rg -nF "${symbol}" within these files.`;
238|
239|    return prefixReadWarnings(
240|      (rolledUp ? `${header}\n${body}` : body) + locationsNote + trustLine + confidenceFooter,
241|      freshness.warnings,
242|    );
243|  } finally {
244|    db.close();
245|  }
