{"content": "1|import { join } from 'node:path';
2|import { openExistingDb } from '../../storage/db.js';
3|import { renderCompact } from '../renderer.js';
4|import { rankCallees } from '../rank.js';
5|import { enforceBudget } from '../budget.js';
6|import { buildAmbiguousMatchMessage, resolveSymbol } from './symbol_lookup.js';
7|import { selectBestRoot } from './path.js';
8|import { inspectReadFreshness, prefixReadWarnings, staleNotFoundCaveat } from './read_freshness.js';
9|import { buildTrustLine, buildAbsenceTrustLine, ABSENCE_TRUST_UNAVAILABLE, RESULTS_TRUST_UNAVAILABLE } from '../lsp-evidence.js';
10|import { indexedScopePhrase } from '../miss-scope.js';
11|import { EXECUTION_FAMILY, CALL_FAMILY } from '../../storage/taxonomy.js';
12|import { normalizePathArg } from '../../util/paths.js';
13|import { scanDynamicBoundaries, renderDynamicBoundaries, readSymbolBody } from '../dynamic-boundaries.js';
14|import { noMatchMessage } from '../did-you-mean.js';
15|// ⚠ Shared with graph_callers. This verb is the exact MIRROR — same narrowing, outgoing
16|// instead of incoming — so it gets the same owner rather than a pasted copy that can drift.
17|import { unsearchedRelationNote } from '../unsearched-scope.js';
18|
19|const EXECUTION_RELATIONS = EXECUTION_FAMILY;
20|
21|// ⛔ A CAP IS NOT A COUNT, and this verb had THREE bare `LIMIT 100`s — the exact defect written up
22|// as "worse" about graph_impact, in the direct mirror of graph_callers. Ask who calls X and the
23|// answer said "at least N"; ask what X calls and it capped silently. Found by an outside reviewer
24|// enumerating renderCompact's callers after I fixed two of seven and wrote "both verbs".
25|// Each query asks for one MORE than is kept, purely so saturation is detectable.
26|const CALLEE_FETCH_CAP = 100;
27|
28|// ⛔ DERIVED BY SUBTRACTION, never listed — a relation joining CALL_FAMILY is covered with no edit.
29|// Measured on click: 71 of 88 "NO CALLEES" answers (81%) had unsearched OUTGOING edges.
30|const UNSEARCHED_RELATIONS = Object.freeze(CALL_FAMILY.filter((r) => !EXECUTION_FAMILY.includes(r)));
31|
32|export async function graphCallees({ repoRoot, symbol, depth = 1, top_k = 10, file }) {
33|  if (!symbol) return 'ERROR: symbol parameter is required';
34|  file = normalizePathArg(file); // accept Windows backslash file filters (mirror graph_callers)
35|  const freshness = await inspectReadFreshness({ repoRoot, verbName: 'graph_callees' });
36|  if (freshness.blocker) return freshness.blocker;
37|  const db = openExistingDb(join(repoRoot, '.aify-graph', 'graph.sqlite'));
38|  try {
39|    const sources = resolveSymbol(db, symbol);
40|    // ⛔ A NOT-FOUND IS A CLAIM, AND A STALE INDEX MAKES IT A FALSE ONE. `staleNotFoundCaveat` is
41|    // MEASURED (n commits behind HEAD) and SILENT on a fresh index, so it adds no noise on the happy
42|    // path — the standard the whereis miss-scope work set: a generic "may be incomplete" costs the
43|    // reader as much as a false claim. find/search/whereis already did this; these did not.
44|    if (sources.length === 0) return [noMatchMessage(db, symbol), staleNotFoundCaveat(freshness)].filter(Boolean).join('\n');
45|    const ambiguity = buildAmbiguousMatchMessage(symbol, sources);
46|    if (ambiguity) return ambiguity;
47|    const root = selectBestRoot(sources);
48|    const sourceIds = [root.id];
49|    // ⚠ HOISTED. These were declared inside the depth<=1 branch, so the absence path below could not
50|    // see them. The scope note needs the same target set the query used — reconstructing it there
51|    // would be a second implementation of "which nodes is this about".
52|    const scopePlaceholders = sourceIds.map((_, i) => `$s${i}`).join(',');
53|    const scopeParams = {};
54|    sourceIds.forEach((id, i) => { scopeParams[`s${i}`] = id; });
55|
56|    let edges;
57|    if (depth <= 1) {
58|      const placeholders = sourceIds.map((_, i) => `$s${i}`).join(',');
59|      const params = {};
60|      sourceIds.forEach((id, i) => { params[`s${i}`] = id; });
61|      edges = db.all(
62|        `SELECT e.*, n.label AS to_label, n.type AS to_type, n.file_path AS to_file, n.start_line AS to_line
63|         FROM edges e JOIN nodes n ON n.id = e.to_id
64|         WHERE e.from_id IN (${placeholders}) AND e.relation IN (${EXECUTION_RELATIONS.map((relation) => `'${relation}'`).join(',')})
65|         -- Mirror rankCallees so the SQL cut and the final ranking agree: a
66|         -- verified edge late in the body must not be dropped by LIMIT in favour
67|         -- of a heuristic one early in it. Without any ORDER BY at all this
68|         -- LIMIT truncated arbitrarily.
69|         ORDER BY CASE WHEN e.provenance = 'LSP_VERIFIED' THEN 0 ELSE 1 END,
70|                  e.source_line, n.label
71|         LIMIT ${CALLEE_FETCH_CAP + 1}`,
72|        params
73|      );
74|    } else {
75|      const sid = root.id;
76|      edges = db.all(
77|        `WITH RECURSIVE callees(from_id, to_id, depth) AS (
78|           SELECT from_id, to_id, 1
79|           FROM edges
80|           WHERE from_id = $sid AND relation IN (${EXECUTION_RELATIONS.map((relation) => `'${relation}'`).join(',')})
81|           UNION ALL
82|           SELECT e.from_id, e.to_id, c.depth + 1
83|           FROM edges e
84|           JOIN callees c ON e.from_id = c.to_id
85|           WHERE e.relation IN (${EXECUTION_RELATIONS.map((relation) => `'${relation}'`).join(',')}) AND c.depth < $depth AND c.depth <= 10
86|         )
87|         SELECT DISTINCT e.*, n.label AS to_label, n.type AS to_type, n.file_path AS to_file, n.start_line AS to_line, c.depth
88|         FROM callees c
89|         JOIN edges e
90|           ON e.from_id = c.from_id
91|          AND e.to_id = c.to_id
92|          AND e.relation IN (${EXECUTION_RELATIONS.map((relation) => `'${relation}'`).join(',')})
93|         JOIN nodes n ON n.id = e.to_id
94|         ORDER BY CASE WHEN e.provenance = 'LSP_VERIFIED' THEN 0 ELSE 1 END,
95|                  c.depth, e.source_line, n.label
96|         LIMIT ${CALLEE_FETCH_CAP + 1}`,
97|        { sid, depth }
98|      );
99|    }
100|
101|    // P0-5: a base virtual's dynamic-dispatch callees are its derived
102|    // override implementations. clangd resolves `base*->virt()` to the declared
103|    // base method only; OVERRIDDEN_BY (base→derived, INFERRED) lets callees
104|    // continue through vtable dispatch. Query forward from the root and merge.
105|    // Marked INFERRED in output. The verified override set is
106|    // code_intel_hierarchy kind=subtypes on the OWNING CLASS (clangd returns the
107|    // derived classes; their same-named methods are the overrides). NOTE: passing
108|    // the METHOD to kind=subtypes resolves to the method's return type, not its
109|    // overrides — validated against real clangd on echoes ISimDomain.
110|    let overrideEdges = db.all(
111|      `SELECT e.*, n.label AS to_label, n.type AS to_type, n.file_path AS to_file, n.start_line AS to_line
112|       FROM edges e JOIN nodes n ON n.id = e.to_id
113|       WHERE e.from_id = $sid AND e.relation = 'OVERRIDDEN_BY'
114|       LIMIT ${CALLEE_FETCH_CAP + 1}`,
115|      { sid: root.id },
116|    );
117|
118|    // Either fetch saturating makes the rendered remainder a floor rather than a total. Both are
119|    // consulted because both feed the same rendered list, and a floor in one half is a floor.
120|    //
121|    // ⚠ AND BOTH MUST BE SLICED BACK. The extra row is fetched ONLY to detect saturation and is
122|    // never shown — `overrideMapped` bypasses `enforceBudget` and renders in full, so leaving the
123|    // probe row in would display one override more than the cap allows. I introduced exactly that
124|    // off-by-one here by changing the LIMIT and not the slice, which is the shape of every
125|    // "computed and not consumed" defect in this file's history, running the other way.
126|    const edgesTruncated = edges.length > CALLEE_FETCH_CAP
127|      || overrideEdges.length > CALLEE_FETCH_CAP;
128|    if (edges.length > CALLEE_FETCH_CAP) edges = edges.slice(0, CALLEE_FETCH_CAP);
129|    if (overrideEdges.length > CALLEE_FETCH_CAP) overrideEdges = overrideEdges.slice(0, CALLEE_FETCH_CAP);
130|
131|    // I1 — gate the absence claim on exhaustive evidence (see callers.js).
132|    const absence = async (msg) => {
133|      // ⛔ BEFORE THE FIRST AWAIT. Callers `return` this promise, so the enclosing
134|      // `finally { db.close() }` has already run by the time an awaited continuation resumes — a db
135|      // read placed after the await throws on every call and the catch returns '', leaving the
