{"content": "1|export function rankCallers(edges) {
2|  return [...edges].sort((a, b) => {
3|    // LSP_VERIFIED (clangd ground truth) always ranks above heuristic edges —
4|    // it is never rendered or ordered as equal to a tree-sitter/heuristic edge
5|    // (Code-Intel v2 / L2b). This also keeps verified edges out of the
6|    // budget-drop tail (enforceBudget applies the same priority).
7|    const v = lspPriority(b) - lspPriority(a);
8|    if (v !== 0) return v;
9|    const d = (a.depth ?? 1) - (b.depth ?? 1);
10|    if (d !== 0) return d;
11|    const c = (b.confidence ?? 0) - (a.confidence ?? 0);
12|    if (c !== 0) return c;
13|    const t = testProximity(b) - testProximity(a);
14|    if (t !== 0) return t;
15|    return (b.fan_in ?? 0) - (a.fan_in ?? 0);
16|  });
17|}
18|
19|// Callees are not callers reversed. "Who calls X" is a set — order is a ranking
20|// question. "What does X call" is a SEQUENCE: the agent is reading a function
21|// body and wants the calls in the order they occur, the way they would reading
22|// the source.
23|//
24|// rankCallees used to be a literal alias of rankCallers, and for a callee list
25|// every one of that function's tiebreakers is constant: depth is 1 at the
26|// default, fan_in is hardcoded to 1 by the caller, from_type is always
27|// 'Function'. All tiers collapsed, the sort fell through to arbitrary SQL row
28|// order, and the output read as scrambled/alphabetical (field report). Ordering
29|// by call-site line makes it both meaningful AND deterministic.
30|export function rankCallees(edges) {
31|  return [...edges].sort((a, b) => {
32|    // Ground truth still outranks heuristics — an LSP-verified callee is not
33|    // interleaved with guesses just because it appears later in the body.
34|    const v = lspPriority(b) - lspPriority(a);
35|    if (v !== 0) return v;
36|    const d = (a.depth ?? 1) - (b.depth ?? 1);
37|    if (d !== 0) return d;
38|    // Call-site order within the body. `call_line` is the line of the CALL, not
39|    // of the callee's definition — the two were conflated before, which is why
40|    // ordering could not reflect the body at all.
41|    const l = (a.call_line ?? Number.MAX_SAFE_INTEGER) - (b.call_line ?? Number.MAX_SAFE_INTEGER);
42|    if (l !== 0) return l;
43|    return String(a.to_label ?? '').localeCompare(String(b.to_label ?? ''));
44|  });
45|}
46|
47|// Shared LSP-verified priority. 1 for clangd ground-truth edges, 0 otherwise.
48|// Used by rank.js (ordering) and budget.js (drop-order) so verified edges sort
49|// first and are never the ones dropped first under a top_k budget.
50|export function lspPriority(edge) {
51|  return edge?.provenance === 'LSP_VERIFIED' ? 1 : 0;
52|}
53|
54|function testProximity(edge) {
55|  return edge.from_type === 'Test' ? 1 : 0;
