21|import { rankCallees } from '../../../mcp/stdio/query/rank.js';
22|import { openDb } from '../../../mcp/stdio/storage/db.js';
23|
24|function node(db, id, label, file, line) {
25|  db.run(
26|    `INSERT INTO nodes (id,type,label,file_path,start_line,end_line,language,confidence,extra)
27|     VALUES ($id,'Function',$label,$file,$line,$end,'cpp',1,'{}')`,
28|    { id, label, file, line, end: line + 2 });
29|}
30|
31|describe('graph_callees returns calls in body order', () => {
32|  let repoRoot;
33|
34|  beforeEach(async () => {
35|    repoRoot = await mkdtemp(join(tmpdir(), 'apg-callorder-'));
36|    await mkdir(join(repoRoot, '.aify-graph'), { recursive: true });
37|  });
38|  afterEach(async () => { try { await rm(repoRoot, { recursive: true, force: true }); } catch {} });
39|
40|  it('orders callees by call-site line, not by callee definition line', async () => {
41|    const db = openDb(join(repoRoot, '.aify-graph', 'graph.sqlite'));
42|    node(db, 'root', 'orchestrate', 'src/run.cpp', 10);
43|    // Definition lines are DESCENDING while call-site lines ASCEND, so a list
44|    // ordered by the wrong field comes out exactly reversed. Labels are also
45|    // reverse-alphabetical to the call order, catching an alphabetical fallback.
46|    const callees = [
47|      { id: 'z', label: 'zeta_first', defLine: 900, callLine: 11 },
48|      { id: 'm', label: 'mu_second', defLine: 600, callLine: 12 },
49|      { id: 'a', label: 'alpha_third', defLine: 300, callLine: 13 },
50|    ];
51|    for (const c of callees) {
52|      node(db, c.id, c.label, 'src/lib.cpp', c.defLine);
53|      db.run(
54|        `INSERT INTO edges (from_id,to_id,relation,source_file,source_line,confidence,provenance,extractor)
55|         VALUES ('root',$to,'CALLS','src/run.cpp',$line,1.0,'EXTRACTED','cpp')`,
56|        { to: c.id, line: c.callLine });
57|    }
58|    db.close();
59|
60|    const out = await graphCallees({ repoRoot, symbol: 'orchestrate' });
61|
62|    const order = ['zeta_first', 'mu_second', 'alpha_third']
63|      .map((label) => out.indexOf(label));
64|    expect(order.every((i) => i >= 0)).toBe(true);
65|    expect(order[0]).toBeLessThan(order[1]);
66|    expect(order[1]).toBeLessThan(order[2]);
67|  });
