69|  it('rankCallees still puts ground truth ahead of a heuristic earlier in the body', () => {
70|    // Ordering by body position must not interleave a verified edge with guesses.
71|    const ranked = rankCallees([
72|      { to_label: 'guess_at_top', call_line: 1, provenance: 'EXTRACTED' },
73|      { to_label: 'verified_lower', call_line: 99, provenance: 'LSP_VERIFIED' },
74|    ]);
75|    expect(ranked.map((e) => e.to_label)).toEqual(['verified_lower', 'guess_at_top']);
76|  });
77|
78|  it('rankCallees is deterministic when call lines are absent', () => {
79|    // Missing call_line must degrade to a stable label order, not arbitrary order.
80|    const edges = [
81|      { to_label: 'charlie', provenance: 'EXTRACTED' },
82|      { to_label: 'alpha', provenance: 'EXTRACTED' },
83|      { to_label: 'bravo', provenance: 'EXTRACTED' },
84|    ];
85|    expect(rankCallees(edges).map((e) => e.to_label)).toEqual(['alpha', 'bravo', 'charlie']);
86|  });
