{"content": "1|// Output mode resolution. Precedence:
2|//   1. explicit `compact` flag passed to a render call
3|//   2. env var AIFY_GRAPH_OUTPUT=compact|verbose
4|//   3. default = verbose (backward-compatible)
5|//
6|// Compact mode strips repeated symbols, `EDGE`/arrow noise, and default
7|// confidence values. Target: 25-50% fewer tokens on impact/callers/path
8|// without losing information the caller actually needs.
9|function defaultCompactFromEnv() {
10|  const envMode = (process.env.AIFY_GRAPH_OUTPUT || '').toLowerCase();
11|  return envMode === 'compact';
12|}
13|
14|function useCompact(opts) {
15|  if (opts && typeof opts.compact === 'boolean') return opts.compact;
16|  return defaultCompactFromEnv();
17|}
18|
19|function formatLocation(filePath, line) {
20|  if (filePath === 'external') return 'external';
21|  if (filePath && filePath.length > 0) return `${filePath}:${line ?? 0}`;
22|  return 'external';
23|}
24|
25|export function renderNodeLine(n) {
26|  return `NODE ${n.id} ${(n.type ?? 'unknown').toLowerCase()} ${n.label} ${formatLocation(n.file_path, n.start_line)}`;
27|}
28|
29|// Provenance tag: only show when NOT the default EXTRACTED (the AST case).
30|// INFERRED / AMBIGUOUS are the signals worth surfacing — they tell agents
31|// "this edge came from heuristic resolution or framework synthesis, treat
32|// it with less trust." EXTRACTED stays silent to keep output terse.
33|//
34|// LSP_VERIFIED (Code-Intel v2 / L2b) is clangd ground truth and must NEVER
35|// render as equal to a heuristic edge. It gets a distinct, always-on inline
36|// marker `[lsp✓]` so an agent can tell verified edges from heuristic ones at
37|// a glance — even in compact mode, where EXTRACTED is silenced for terseness.
38|const LSP_VERIFIED_MARKER = '[lsp✓]';
39|export function renderProvenanceTag(p) {
40|  if (!p || p === 'EXTRACTED') return '';
41|  if (p === 'LSP_VERIFIED') return ` ${LSP_VERIFIED_MARKER}`;
42|  return ` prov=${p}`;
43|}
44|
45|// Verbose edge line (original format, preserved for backward compat).
46|function renderEdgeVerbose(e) {
47|  const conf = ` conf=${Number(e.confidence ?? 1.0).toFixed(2)}`;
48|  const prov = renderProvenanceTag(e.provenance);
49|  const fromRef = e.from_label ?? e.from_id;
50|  const toRef = e.to_label ?? e.to_id;
51|  return `EDGE ${fromRef}→${toRef} ${e.relation} ${e.source_file ?? '?'}:${e.source_line ?? '?'}${conf}${prov}`;
52|}
53|
54|// Compact edge line: `<caller_file>:<caller_line> <from_label> <rel> <to_label>`.
55|// Direction is explicit (from → rel → to), caller location leads for quick
56|// navigation. Drops `EDGE` prefix, drops `→` arrow noise, drops default
57|// confidence. ~35-45% shorter than verbose while staying unambiguous.
58|// If `to_label` is unavailable we omit it (query context supplies it).
59|function renderEdgeCompact(e) {
60|  const loc = `${e.source_file ?? '?'}:${e.source_line ?? '?'}`;
61|  const from = e.from_label ?? e.from_id ?? '?';
62|  const to = e.to_label ? ` ${e.to_label}` : '';
63|  const conf = Number(e.confidence ?? 1.0);
64|  const confTag = conf < 0.75 ? ` conf=${conf.toFixed(2)}` : '';
65|  const provTag = renderProvenanceTag(e.provenance);
66|  return `${loc} ${from} ${e.relation}${to}${confTag}${provTag}`;
67|}
68|
69|export function renderEdgeLine(e, opts) {
70|  return useCompact(opts) ? renderEdgeCompact(e) : renderEdgeVerbose(e);
71|}
72|
73|/**
74| * ⛔ THE REMAINDER IS ONLY A NUMBER IF THE SET IT WAS SUBTRACTED FROM WAS COMPLETE.
75| *
76| * `truncated` is display budget: how many rows the renderer dropped to fit `top_k`. It is computed
77| * as (rows the verb held) − (rows shown). When the verb's own FETCH saturated at a cap, the rows it
78| * held are themselves a floor, so the remainder is a floor too and "TRUNCATED 70 more" states a
79| * total the query never established.
80| *
81| * ⭐ FOUND 2026-09-07 BY DRIVING THE REAL VERB, not by reading it. `graph_impact` on a fan-in of
82| * 101 printed 30 rows and "TRUNCATED 70 more" — implying exactly 100 — with no confidence line at
83| * all, because the floor language shipped that morning sits behind `if (suspicious)` and this
84| * symbol was not suspicious. The fix went into the line that sometimes prints and not the line that
85| * always does. `graph_callers` had the identical hole; one owner, so it is repaired once.
86| *
87| * ⛔⛔ AND THE FLAG IS REQUIRED, NOT DEFAULTED — because the first version of this fix defaulted it
88| * to `false` and an outside reviewer named that as the defect wearing the shape of a fix. A default
89| * makes the repair OPT-IN PER VERB: seven verbs call this, and the two I had in mind when I wrote
90| * "both verbs" were the two I happened to be editing. `callees` and `neighbors` would have kept the
91| * old behaviour silently, and `callees` is the direct mirror of the verb I had just fixed.
92| *
93| * ⭐ DERIVE ALLOWED VALUES, NEVER LIST THEM — and where a value cannot be derived here, refuse
94| * instead of guessing. A remainder is only a number if the set it was subtracted from was complete,
95| * so a caller that reports a remainder must state whether that set was. Callers that report no
96| * remainder never have to answer, which is why this does not become noise at the other five sites.
97| *
98| * @param {boolean} truncatedIsFloor  did the verb's fetch saturate, making the remainder a floor.
99| *                                    REQUIRED whenever `truncated > 0`.
100| */
101|export function renderCompact(
102|  { nodes = [], edges = [], truncated = 0, suggestion = '', truncatedIsFloor },
103|  opts,
104|) {
